            result['stderr'] = stderr
    except Exception as e:
        result = _error_result(
            jid, e, started=1, cmd=wrapped_cmd,
            stdout=to_text(outdata, errors='surrogate_or_strict'),
            stderr=to_text(stderr, errors='surrogate_or_strict'),
            exception=traceback.format_exc(),
        )
    else:
        result['ansible_job_id'] = jid
        result['started'] = 1
        result['finished'] = 1
        result.setdefault('failed', False)

    jwrite(result)


def _record_error(result):
    try:
        jwrite(result)
    except Exception as e:
        result['msg'] += '; could not write job result: %s' % to_text(e)


def _supervise(sub_pid, time_limit, jid, wrapped_module, preserve_tmp):
    # The worker owns the notifier. The supervisor only watches its process group.
    ipc_notifier.close()
    try:
        os.setpgid(sub_pid, sub_pid)
    except OSError as e:
        if e.errno != errno.ESRCH:
            raise

    notice('Start watching %s (%s)' % (sub_pid, time_limit))
    remaining = time_limit
    step = 5
    while os.waitpid(sub_pid, os.WNOHANG) == (0, 0):
        if remaining <= 0:
            notice('Now killing %s' % sub_pid)
            try:
                os.killpg(sub_pid, signal.SIGKILL)
            except OSError as e:
                if e.errno != errno.ESRCH:
                    raise
                # The worker completed between waitpid and killpg.
                os.waitpid(sub_pid, 0)
                break
