            jwrite(_error_result(
                jid, 'Async task exceeded time limit of %s seconds (child PID %s)' % (time_limit, sub_pid),
                started=1, child_pid=sub_pid,
            ))
            break
        time.sleep(min(step, remaining))
        remaining -= step

    notice('Done in async supervisor.')
    _cleanup_tmp(wrapped_module, preserve_tmp)
    end(None, 0)


def _run_background(cmd, jid, wrapped_module, preserve_tmp, time_limit):
    started = 0
    try:
        ipc_watcher.close()
        daemonize_self()
        notice('Starting module and watcher')
        sub_pid = os.fork()
        started = 1
        if sub_pid:
            _supervise(sub_pid, time_limit, jid, wrapped_module, preserve_tmp)
        else:
            # Establish the group before Popen so the module also joins it.
            os.setpgid(0, 0)
            notice('Start module (%s)' % os.getpid())
            _run_module(cmd, jid, job_path)
            notice('Module complete (%s)' % os.getpid())
            end(None, 0)
    except SystemExit:
        raise
    except Exception as e:
        notice('Async wrapper error: %s' % to_text(e))
        result = _error_result(jid, 'FATAL ERROR: %s' % to_text(e), started=started,
                               exception=traceback.format_exc())
        _record_error(result)
        _notify_parent(result)
        _cleanup_tmp(wrapped_module, preserve_tmp)
        end(None, 1)


def main():
    global job_path
    if len(sys.argv) < 5:
        end(_error_result(None, 'usage: async_wrapper <jid> <time_limit> <modulescript> '
                                '<argsfile> [-preserve_tmp]  Humans, do not call directly!'), 1)

    jid = "%s.%d" % (sys.argv[1], os.getpid())
    wrapped_module = sys.argv[3]
    argsfile = sys.argv[4]
    if '-tmp-' not in os.path.dirname(wrapped_module):
        preserve_tmp = True
    elif len(sys.argv) > 5:
        preserve_tmp = sys.argv[5] == '-preserve_tmp'
    else:
        preserve_tmp = False
    # consider underscore as no argsfile so we can support passing of additional positional parameters
    if argsfile != '_':
        cmd = "%s %s" % (wrapped_module, argsfile)
    else:
        cmd = wrapped_module

    async_dir = os.environ.get('ANSIBLE_ASYNC_DIR', '~/.ansible_async')

    # setup job output directory
    jobdir = os.path.expanduser(async_dir)
    job_path = os.path.join(jobdir, jid)

    try:
        time_limit = int(sys.argv[2])
        if time_limit < 0:
            raise ValueError('time_limit must be zero or greater')
        _make_temp_dir(jobdir)
    except Exception as e:
        result = _error_result(jid, 'Could not set up async job in %s: %s' % (jobdir, to_text(e)),
                               exception=traceback.format_exc(), results_file=job_path,
                               _ansible_suppress_tmpdir_delete=not preserve_tmp)
        _cleanup_tmp(wrapped_module, preserve_tmp)
        end(result, 1)

    # immediately exit this process, leaving an orphaned process
    # running which immediately forks a supervisory timing process

    try:
        pid = os.fork()
    except Exception as e:
        result = _error_result(jid, 'fork failed: %s' % to_text(e),
                               exception=traceback.format_exc(), results_file=job_path,
                               _ansible_suppress_tmpdir_delete=not preserve_tmp)
        _record_error(result)
        _cleanup_tmp(wrapped_module, preserve_tmp)
        end(result, 1)

    if not pid:
        _run_background(cmd, jid, wrapped_module, preserve_tmp, time_limit)
        return

    # Wait briefly for the worker's first job record before returning to the controller.
    ipc_notifier.close()
    notification = None
    try:
        for unused in range(25):
            if ipc_watcher.poll(0.1):
                notification = ipc_watcher.recv()
                break
    except EOFError:
        pass
    except Exception as e:
        result = _error_result(jid, 'Could not receive async startup status: %s' % to_text(e),
                               results_file=job_path, _ansible_suppress_tmpdir_delete=not preserve_tmp)
        _record_error(result)
        end(result, 1)
    finally:
        ipc_watcher.close()

    if isinstance(notification, dict):
        notification['results_file'] = job_path
        notification['_ansible_suppress_tmpdir_delete'] = not preserve_tmp
        end(notification, 1)

    notice('Return async_wrapper task started.')

